      "ja": "関西学院大学公式サイト（2021年2月・2025年12月の記事）、BiZCAFE神戸三田店 公式Instagram",
      "text": "关西学院大学官方网站（2021年2月、2025年12月的文章）、BiZCAFE神户三田店官方Instagram",
