    "facultyGuide.faculties.bes.name": {
      "ja": "生命環境学部",
      "text": "生命环境系",
      "status": "official"
    },
    "facultyGuide.faculties.bes.lead": {
      "ja": "環境・食糧・健康など、現代社会の課題の解決に挑む力を身につける学部です。実験科学とデータサイエンスを活かした教育・研究に取り組んでいます。",
      "text": "培养挑战环境、粮食、健康等现代社会课题之能力的学部。开展运用实验科学和数据科学的教育与研究。",
      "status": "provisional"
    },
